  type: 'takeGlobalCursor',
  key: 'dataZoomSelect',
  dataZoomSelectActive: true,
}), 500);

function closestBinarySearch(values, elmt) {
  let min = 0;
  let max = values.length - 1;
  if (elmt <= values[min][0]) {
    return [min, min];
  }
  if (elmt >= values[max][0]) {
    return [max, max];
  }
  let mid = 0;
  while (min < max) {
    let mid = Math.floor((max + min) / 2);
    if (elmt === values[mid][0]) {
      return [mid, mid];
    } else if (elmt < values[mid][0]) {
      if (mid > 0 && elmt > values[mid - 1][0]) {
        return [mid - 1, mid];
      }
      max = mid;
    } else {
      if (mid < values.length - 1 && elmt < values[mid + 1][0]) {
        return [mid, mid + 1];
      }
      min = mid + 1;
    }
  }
  return [mid, mid + 1];
}

return res;

